vulnerable_function:
def parsedkim(line):
    if '"' in line:
        add = 0
        dk = ""
        for x in line.split('"'):
            add ^= 1
            if add == 0:
                dk += x
    else:
        dk = line

    dkim = {}
    for x in dk.split(";"):
        s = x.split("=", 1)
        if len(s) != 2:
            continue
        key = s[0].strip()
        value = s[1].strip()
        dkim[key] = value
    if "p" not in dkim:
        return False
    if dkim["p"] == "":
        return False
    if "k" not in dkim:
        dkim["k"] = "rsa"

    if dkim["k"] == "rsa":
        return PUBPRE + dkim["p"] + PUBPOST
    if dkim["k"] == "ed25519":
        try:
            rawed = base64.b64decode(dkim["p"].encode("ascii"))
        except (binascii.Error, UnicodeEncodeError):
            return False
        if len(rawed) != 32:
            return False
        der = EDASN1 + rawed
        return PUBPRE + base64.b64encode(der).decode() + PUBPOST
    _warnmsg(f"Unknown DKIM key type {dkim['k']}")
    return False

